<?php
namespace App\Controllers;
use App\Core\Controller;
use App\Core\Database;
use App\Models\Customer;
use App\Models\Product;
use App\Models\Sale;
use App\Models\Setting;
use App\Services\AuditService;
final class PosController extends Controller {
 public function index():void{$db=Database::connection();$st=$db->prepare("SELECT cs.*,r.name register_name FROM cash_sessions cs JOIN registers r ON r.id=cs.register_id WHERE cs.user_id=? AND cs.status='OPEN' ORDER BY cs.id DESC LIMIT 1");$st->execute([$_SESSION['user']['id']]);$session=$st->fetch()?:null;$cart=$_SESSION['pos_cart']??[];$products=[];$total=0;$pm=new Product();foreach($cart as $pid=>$qty){$p=$pm->find((int)$pid);if($p){$p['cart_qty']=$qty;$p['line_total']=$qty*(float)($p['effective_price']??$p['sale_price']);$products[]=$p;$total+=$p['line_total'];}}$customers=(new Customer())->allCustomers();$rate=(float)(new Setting())->get('usd_cdf_rate',2850);$registers=$db->query("SELECT * FROM registers WHERE status='ACTIVE'")->fetchAll();$this->view('pos/index',compact('session','products','total','customers','rate','registers')+['title'=>'KIN-MART POS']);}
 public function open():void{$db=Database::connection();$check=$db->prepare("SELECT id FROM cash_sessions WHERE user_id=? AND status='OPEN'");$check->execute([$_SESSION['user']['id']]);if($check->fetch()){flash('error','Une caisse est déjà ouverte.');redirect('pos');}$db->prepare("INSERT INTO cash_sessions(register_id,user_id,opening_amount,status,opened_at) VALUES(?,?,?,'OPEN',NOW())")->execute([(int)$_POST['register_id'],$_SESSION['user']['id'],(float)$_POST['opening_amount']]);flash('success','Caisse ouverte.');redirect('pos');}
 public function add():void{$code=trim($_POST['code']??'');$pid=(int)($_POST['product_id']??0);$pm=new Product();$p=$pid?$pm->find($pid):$pm->findByBarcodeOrCode($code);if(!$p){flash('error','Produit introuvable.');redirect('pos');}$avail=(float)($p['available_qty']??((float)$p['quantity']-(float)($p['reserved_quantity']??0)));$qty=max(1,(float)($_POST['qty']??1));$current=(float)($_SESSION['pos_cart'][$p['id']]??0);if($current+$qty>$avail){flash('error','Stock disponible insuffisant.');redirect('pos');}$_SESSION['pos_cart'][$p['id']]=$current+$qty;redirect('pos');}
 public function update():void{$pid=(int)$_POST['product_id'];$qty=(float)$_POST['qty'];if($qty<=0)unset($_SESSION['pos_cart'][$pid]);else $_SESSION['pos_cart'][$pid]=$qty;redirect('pos');}
 public function checkout():void{$cart=$_SESSION['pos_cart']??[];if(!$cart){flash('error','Panier vide.');redirect('pos');}$db=Database::connection();$st=$db->prepare("SELECT id FROM cash_sessions WHERE user_id=? AND status='OPEN' ORDER BY id DESC LIMIT 1");$st->execute([$_SESSION['user']['id']]);$sid=$st->fetchColumn();if(!$sid){flash('error','Ouvrez une caisse avant la vente.');redirect('pos');}$rate=(float)(new Setting())->get('usd_cdf_rate',2850);$currency=$_POST['currency']??'CDF';$method=$_POST['method']??'ESPECES';$received=(float)($_POST['received_amount']??0);$cartTotal=0;$pm=new Product();foreach($cart as $pid=>$q){$p=$pm->find((int)$pid);$cartTotal+=(float)($p['effective_price']??$p['sale_price'])*$q;}$discount=max(0,(float)($_POST['discount']??0));$pointsUse=max(0,(int)($_POST['points_use']??0));$pointsDiscount=0.0;if(($_POST['customer_id']??'')!==''&&$pointsUse>0){$cid=(int)$_POST['customer_id'];$acc=$db->prepare("SELECT points_balance FROM loyalty_accounts WHERE customer_id=?");$acc->execute([$cid]);$bal=(int)($acc->fetchColumn()?:0);$threshold=(int)(new Setting())->get('loyalty_points_per_reward',100);$reward=(float)(new Setting())->get('loyalty_reward_usd',1);$groups=$threshold>0?intdiv(min($pointsUse,$bal),$threshold):0;$pointsDiscount=$groups*$reward;}$total=max(0,$cartTotal-$discount-$pointsDiscount);$expected=$currency==='CDF'?$total*$rate:$total;$change=max(0,$received-$expected);$payment=['method'=>$method,'currency'=>$currency,'amount'=>$total,'exchange_rate'=>$currency==='CDF'?$rate:1,'reference_no'=>trim($_POST['reference_no']??''),'received_amount'=>$received,'change_amount'=>$change];try{$sale=(new Sale())->createSale($cart,($_POST['customer_id']??'')!==''?(int)$_POST['customer_id']:null,$payment,(int)$_SESSION['user']['id'],(int)$sid,$discount,$pointsUse);unset($_SESSION['pos_cart']);AuditService::log('CREATE','SALE',null,$sale);redirect('sales/'.$sale['id'].'/receipt');}catch(\Throwable $e){flash('error',$e->getMessage());redirect('pos');}}
 public function receipt(string $id):void{$sale=(new Sale())->find((int)$id);if(!$sale){flash('error','Vente introuvable.');redirect('pos');}$settings=(new Setting())->allSettings();$this->view('pos/receipt',compact('sale','settings')+['title'=>'Ticket '.$sale['sale_no']],false);}
 public function close():void{$db=Database::connection();$st=$db->prepare("SELECT * FROM cash_sessions WHERE user_id=? AND status='OPEN' ORDER BY id DESC LIMIT 1");$st->execute([$_SESSION['user']['id']]);$s=$st->fetch();if(!$s){flash('error','Aucune caisse ouverte.');redirect('pos');}$tot=$db->prepare("SELECT COALESCE(SUM(sa.total),0) FROM sales sa WHERE sa.cash_session_id=? AND sa.status='COMPLETED'");$tot->execute([$s['id']]);$sales=(float)$tot->fetchColumn();$ex=$db->prepare("SELECT COALESCE(SUM(amount),0) FROM cash_expenses WHERE cash_session_id=?");$ex->execute([$s['id']]);$expenses=(float)$ex->fetchColumn();$theo=(float)$s['opening_amount']+$sales-$expenses;$real=(float)$_POST['closing_amount'];$db->prepare("UPDATE cash_sessions SET theoretical_amount=?,closing_amount=?,difference_amount=?,status='CLOSED',closed_at=NOW() WHERE id=?")->execute([$theo,$real,$real-$theo,$s['id']]);flash('success','Caisse clôturée. Écart: '.money($real-$theo));redirect('pos');}

 public function expense():void{$db=Database::connection();$st=$db->prepare("SELECT id FROM cash_sessions WHERE user_id=? AND status='OPEN' ORDER BY id DESC LIMIT 1");$st->execute([$_SESSION['user']['id']]);$sid=$st->fetchColumn();$amount=(float)($_POST['amount']??0);$desc=trim($_POST['description']??'');if(!$sid||$amount<=0||$desc===''){flash('error','Dépense invalide ou caisse fermée.');redirect('pos');}$db->prepare("INSERT INTO cash_expenses(cash_session_id,user_id,description,amount) VALUES(?,?,?,?)")->execute([$sid,$_SESSION['user']['id'],$desc,$amount]);AuditService::log('EXPENSE','CASH',null,['amount'=>$amount,'description'=>$desc]);flash('success','Dépense enregistrée.');redirect('pos');}
}
